			"error: file /run/log/journal/346a500b7fb944199748954baca56086/system.journal: Permission denied",
			models.Package{},
			true,
		},
	}

	for i, tt := range packagetests {
		p, err := r.parseInstalledPackagesLine(tt.in)
		if err == nil && tt.err {
