func (o *redhatBase) needsRestarting() error {
	initName, err := o.detectInitSystem()
	if err != nil {
		o.log.Warn(err)
		// continue scanning
	}

	cmd := "LANGUAGE=en_US.UTF-8 needs-restarting"
	r := o.exec(cmd, sudo)
	if !r.isSuccess() {
		return xerrors.Errorf("Failed to SSH: %w", r)
	}
	procs := o.parseNeedsRestarting(r.Stdout)
	for _, proc := range procs {
		pathFields := strings.Fields(strings.ReplaceAll(proc.Path, "\x00", " "))
		if len(pathFields) == 0 {
			continue
		}
		ownerNames, err := o.getOwnerPkgs(pathFields[:1])
		if err != nil {
			o.log.Warnf("Failed to detect a package name of need restarting process from the command path: %s, %s",
				proc.Path, err)
			continue
		}
		matchedNames := make([]string, 0, len(ownerNames))
		for _, ownerName := range ownerNames {
			if _, ok := o.Packages[ownerName]; ok {
				matchedNames = append(matchedNames, ownerName)
			}
		}
		if len(matchedNames) == 0 {
			continue
		}
		if initName == systemd {
			name, err := o.detectServiceName(proc.PID)
			if err != nil {
				o.log.Warn(err)
				// continue scanning
			}
			proc.ServiceName = name
			proc.InitSystem = systemd
		}
		for _, ownerName := range matchedNames {
			pack := o.Packages[ownerName]
			pack.NeedRestartProcs = append(pack.NeedRestartProcs, proc)
			o.Packages[ownerName] = pack
		}
	}
	return nil
}

func (o *redhatBase) parseNeedsRestarting(stdout string) (procs []models.NeedRestartProcess) {
	scanner := bufio.NewScanner(strings.NewReader(stdout))
	for scanner.Scan() {
		line := scanner.Text()
		line = strings.Replace(line, "\x00", " ", -1) // for CentOS6.9
		ss := strings.Split(line, " : ")
		if len(ss) < 2 {
			continue
		}
		// https://unix.stackexchange.com/a/419375
		if ss[0] == "1" {
			continue
		}

		path := ss[1]
		if !strings.HasPrefix(path, "/") {
			path = strings.Fields(path)[0]
			// [ec2-user@ip-172-31-11-139 ~]$ sudo needs-restarting
			// 2024 : auditd
			// [ec2-user@ip-172-31-11-139 ~]$ type -p auditd
			// /sbin/auditd
			cmd := fmt.Sprintf("LANGUAGE=en_US.UTF-8 which %s", path)
			r := o.exec(cmd, sudo)
			if !r.isSuccess() {
				o.log.Debugf("Failed to exec which %s: %s", path, r)
				continue
			}
			path = strings.TrimSpace(r.Stdout)
		}

		procs = append(procs, models.NeedRestartProcess{
			PID:     ss[0],
			Path:    path,
			HasInit: true,
		})
	}
	return
}

func (o *redhatBase) getOwnerPkgs(paths []string) ([]string, error) {
	quotedPaths := quotePackagePaths(paths)
	if quotedPaths == "" {
		return nil, nil
	}
	cmd := "LANGUAGE=en_US.UTF-8 " + o.rpmQf() + quotedPaths
	r := o.exec(util.PrependProxyEnv(cmd), noSudo)
	// rpm exit code means `the number` of errors.
	// https://listman.redhat.com/archives/rpm-list/2005-July/msg00071.html
	// If we treat non-zero exit codes of `rpm` as errors,
	// we will be missing a partial package list we can get.
	output := r.Stdout
	if r.Stderr != "" {
		output += "\n" + r.Stderr
	}
	if !r.isSuccess() && strings.TrimSpace(output) == "" {
		return nil, xerrors.Errorf("Failed to rpm -qf: %s", r)
	}
	return o.parseOwnerPkgs(output)
}

func (o *redhatBase) parseOwnerPkgs(output string) ([]string, error) {
	ownerNames := []string{}
	seen := map[string]struct{}{}
	scanner := bufio.NewScanner(strings.NewReader(output))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" {
			continue
		}
		pack, err := o.parseInstalledPackagesLine(line)
		if err != nil {
			return nil, err
		}
		if pack.Name == "" {
			continue
		}
		if _, ok := seen[pack.Name]; ok {
			continue
		}
		seen[pack.Name] = struct{}{}
		ownerNames = append(ownerNames, pack.Name)
	}
	if err := scanner.Err(); err != nil {
		return nil, xerrors.Errorf("Failed to read rpm -qf output: %w", err)
	}
	return ownerNames, nil
}

func (o *redhatBase) rpmQa() string {
	const old = `rpm -qa --queryformat "%{NAME} %{EPOCH} %{VERSION} %{RELEASE} %{ARCH}\n"`
	const new = `rpm -qa --queryformat "%{NAME} %{EPOCHNUM} %{VERSION} %{RELEASE} %{ARCH}\n"`
	switch o.Distro.Family {
	case config.SUSEEnterpriseServer:
		if v, _ := o.Distro.MajorVersion(); v < 12 {
			return old
		}
		return new
	default:
		if v, _ := o.Distro.MajorVersion(); v < 6 {
			return old
		}
		return new

// pkgPs associates each running process with packages that own its executable
// or one of its mapped files. The ownership lookup is distribution specific.
func (l *base) pkgPs(getOwnerPkgs func([]string) ([]string, error)) error {
	stdout, err := l.ps()
	if err != nil {
		return xerrors.Errorf("Failed to ps: %w", err)
	}

	pidNames := l.parsePs(stdout)
	pidLoadedFiles := map[string][]string{}
	for pid := range pidNames {
		stdout, err := l.lsProcExe(pid)
		if err != nil {
			l.log.Debugf("Failed to exec /proc/%s/exe: %s", pid, err)
			continue
		}
		path, err := l.parseLsProcExe(stdout)
		if err != nil {
			l.log.Debugf("Failed to parse /proc/%s/exe: %s", pid, err)
			continue
		}
		pidLoadedFiles[pid] = append(pidLoadedFiles[pid], path)

		stdout, err = l.grepProcMap(pid)
		if err != nil {
			l.log.Debugf("Failed to exec /proc/%s/maps: %s", pid, err)
			continue
		}
		pidLoadedFiles[pid] = append(pidLoadedFiles[pid], l.parseGrepProcMap(stdout)...)
	}

	pidListenPorts := map[string][]models.PortStat{}
	stdout, err = l.lsOfListen()
	if err != nil {
		l.log.Warnf("Failed to lsof: %+v", err)
	}
	for ipPort, pids := range l.parseLsOf(stdout) {
		portStat, err := models.NewPortStat(ipPort)
		if err != nil {
			l.log.Warnf("Failed to parse ip:port: %s, err: %+v", ipPort, err)
			continue
		}
		for _, pid := range pids {
			pidListenPorts[pid] = append(pidListenPorts[pid], *portStat)
		}
	}

	var lookupErr error
	for pid, paths := range pidLoadedFiles {
		pkgNames, err := getOwnerPkgs(paths)
		if err != nil {
			l.log.Debugf("Failed to get owning packages for PID %s: %s", pid, err)
			if lookupErr == nil {
				lookupErr = xerrors.Errorf("Failed to get owning packages for PID %s: %w", pid, err)
			}
			continue
		}
		l.addAffectedProcess(pkgNames, models.AffectedProcess{
			PID:             pid,
			Name:            pidNames[pid],
			ListenPortStats: pidListenPorts[pid],
		})
	}
	return lookupErr
}

func (l *base) addAffectedProcess(pkgNames []string, proc models.AffectedProcess) {
	seen := map[string]struct{}{}
	for _, name := range pkgNames {
		if _, exists := seen[name]; exists {
			continue
		}
		seen[name] = struct{}{}
		pack, exists := l.Packages[name]
		if !exists {
			continue
		}
		pack.AffectedProcs = append(pack.AffectedProcs, proc)
		l.Packages[name] = pack
	}
}

func quotePackagePaths(paths []string) string {
	quoted := make([]string, 0, len(paths))
	for _, path := range paths {
		if path == "" {
			continue
		}
		quoted = append(quoted, "'"+strings.ReplaceAll(path, "'", "'\\''")+"'")
	}
	return strings.Join(quoted, " ")
}
}

